/* Go to heaven · Physics question bank (IB Physics, first assessment 2025). */
QB("phys", [
["A.1","Distinguish",2,"Distinguish between distance and displacement.","Distance is a scalar: how far, with no direction|scalar|no direction","Displacement is a vector: the straight-line distance in a given direction|vector|direction|straight line"],
["A.1","Calculate",2,"A car accelerates from rest at 2.0 m s⁻² for 5.0 s. Calculate its final speed.","v = u + at|v u at|2 5","= 10 m s⁻¹|10"],
["A.2","State",1,"State Newton's second law.","The resultant force equals the rate of change of momentum (F = ma)|f ma|rate of change of momentum|proportional to acceleration|acceleration proportional|acceleration is proportional"],
["A.2","Calculate",2,"A 1200 kg car moves at 15 m s⁻¹. Calculate its momentum.","p = mv|p mv|1200 15","= 18 000 kg m s⁻¹|18000|18 000"],
["A.3","Calculate",2,"Calculate the kinetic energy of a 2.0 kg ball moving at 3.0 m s⁻¹.","KE = ½mv²|mv2|half|0.5","= 9.0 J|9"],
["A.3","Define",2,"Define power.","The rate of doing work or transferring energy|rate|work done|energy transferred","Work done ÷ time, measured in watts|time|watt|per second"],
["A.4","Define",2,"Define torque.","The turning effect of a force|turning","Force × perpendicular distance from the axis|perpendicular distance|distance|moment"],
["A.4","State",1,"State the condition for rotational equilibrium.","The resultant torque is zero (clockwise moments = anticlockwise moments)|net torque zero|resultant torque zero|sum of torques|clockwise anticlockwise"],
["A.5","State",2,"State the two postulates of special relativity.","The laws of physics are the same in all inertial frames|laws of physics|same in all|inertial","The speed of light in a vacuum is the same for all observers|speed of light|same for all|constant"],
["A.5","Outline",2,"Outline time dilation.","A moving clock runs slow compared with a stationary observer's|moving clock|runs slow|slower","The effect becomes significant near the speed of light (Lorentz factor γ)|speed of light|gamma|lorentz|high speed"],
["B.1","Define",2,"Define specific heat capacity.","The energy needed to raise the temperature|energy|temperature","Of 1 kg of a substance by 1 K|1 kg|one kilogram|1 k|1 degree|unit mass"],
["B.1","Calculate",2,"Calculate the energy needed to heat 2.0 kg of water by 10 K (c = 4200 J kg⁻¹ K⁻¹).","Q = mcΔT|mc|2 4200 10","= 84 000 J|84000|84 000|84 kj"],
["B.2","Outline",3,"Outline the greenhouse effect.","Short-wave radiation from the Sun passes through the atmosphere and warms the Earth|short wave|shortwave|passes through|visible","The Earth emits infrared (long-wave) radiation|infrared|long wave|longwave","Greenhouse gases absorb and re-emit this infrared, warming the atmosphere|absorb|re emit|reemit|re radiate"],
["B.2","Define",1,"Define albedo.","The fraction of incident radiation that is reflected|fraction reflected|proportion reflected|ratio reflected|percentage reflected|reflected incident|reflected to incoming"],
["B.3","State",1,"State Boyle's law.","For a fixed mass of gas at constant temperature, pressure is inversely proportional to volume|inversely proportional|pv constant"],
["B.3","Outline",2,"Outline how the kinetic model explains gas pressure.","Molecules collide with the walls of the container|collide|collision|walls","Each collision changes their momentum, giving a force per unit area|momentum|force|per unit area|area"],
["B.4","State",1,"State the first law of thermodynamics.","Heat added = change in internal energy + work done by the gas (Q = ΔU + W): energy is conserved|internal energy|conserved|conservation"],
["B.4","Outline",2,"Outline the second law of thermodynamics in terms of entropy.","The total entropy of an isolated system never decreases|entropy|never decreases|increases","So heat flows from hot to cold and no heat engine is 100% efficient|100|efficient|hot to cold"],
["B.5","State",1,"State Ohm's law.","Current is proportional to potential difference at constant temperature (V = IR)|current proportional|proportional to current|proportional to potential difference|proportional to voltage|v ir"],
["B.5","Calculate",2,"Calculate the current through a 6.0 Ω resistor with 12 V across it.","I = V ÷ R|v r|12 6","= 2.0 A|2"],
["C.1","State",2,"State the condition for simple harmonic motion.","Acceleration is proportional to displacement|proportional|displacement","And directed towards the equilibrium position (a = −ω²x)|opposite|towards the equilibrium|towards the centre|minus|negative"],
["C.1","State",2,"State two examples of simple harmonic motion.","A simple pendulum (small swings)|pendulum","A mass on a spring|spring","A vibrating string or tuning fork|string|tuning fork"],
["C.2","Distinguish",2,"Distinguish between transverse and longitudinal waves.","Transverse: oscillations perpendicular to the direction of energy transfer|perpendicular|right angles","Longitudinal: oscillations parallel to the direction of energy transfer|parallel|same direction"],
["C.2","Calculate",2,"A wave has a frequency of 50 Hz and a wavelength of 4.0 m. Calculate its speed.","v = fλ|v f|50 4","= 200 m s⁻¹|200"],
["C.3","Define",2,"Define diffraction.","The spreading of a wave|spread","As it passes through a gap or around an obstacle|gap|obstacle|edge|aperture|slit"],
["C.3","Outline",2,"Outline the conditions for total internal reflection.","Light travels from a denser to a less dense medium|denser|higher refractive index|less dense","The angle of incidence is greater than the critical angle|critical angle|greater"],
["C.4","State",2,"State two differences between standing and travelling waves.","Standing waves do not transfer energy|energy|transfer","Standing waves have nodes and antinodes|node|antinode","In a standing wave the amplitude varies with position|amplitude var|amplitude depends","Points between two nodes oscillate in phase|in phase|phase"],
["C.4","Define",1,"Define resonance.","Large-amplitude oscillation when the driving frequency equals the natural frequency|natural frequency|driving frequency|equals|matches"],
["C.5","Outline",2,"Outline the Doppler effect for a moving sound source.","As the source approaches, the observed frequency (pitch) is higher|higher|approach|towards|shorter wavelength","As it moves away, the observed frequency (pitch) is lower|lower|away|longer wavelength"],
["C.5","State",1,"State what the redshift of a galaxy tells us.","It is moving away from us (the universe is expanding)|moving away|reced|expanding"],
["D.1","State",1,"State Newton's law of universal gravitation.","The force is proportional to the product of the masses and inversely proportional to the square of their separation|product of the masses|inverse square|inversely proportional|square"],
["D.1","Define",2,"Define gravitational field strength.","The force per unit mass|force per unit mass|per kg|per unit mass","On a small test mass placed at that point (N kg⁻¹)|test mass|point|n kg"],
["D.2","State",2,"State Coulomb's law.","The force between two point charges is proportional to the product of the charges|product of the charges|product","And inversely proportional to the square of their separation|inverse square|inversely proportional|square"],
["D.2","Define",1,"Define electric field strength.","The force per unit positive charge (N C⁻¹)|force per unit charge|per unit charge|per coulomb|n c"],
["D.3","Outline",2,"Outline the motion of a charged particle moving at right angles to a uniform magnetic field.","The magnetic force is always perpendicular to its velocity|perpendicular|right angle","So the particle moves in a circle at constant speed|circle|circular"],
["D.3","State",1,"State the equation for the magnetic force on a moving charge.","F = qvB|f qvb|qvb|q v b"],
["D.4","State",1,"State Faraday's law.","The induced emf is proportional to the rate of change of magnetic flux linkage|rate of change of flux|rate of change of magnetic flux|change in flux|flux linkage|emf proportional|emf is proportional"],
["D.4","State",1,"State Lenz's law.","The induced current flows in a direction that opposes the change producing it|oppose"],
["E.1","Outline",2,"Outline what Rutherford's gold foil experiment showed.","Most alpha particles went straight through, so the atom is mostly empty space|empty space|straight through|most passed","A few bounced back, so there is a small, dense, positive nucleus|nucleus|dense|positive|deflected|bounced back"],
["E.1","State",2,"State the relative charges of the proton, the neutron and the electron.","Proton: +1|proton 1|positive|positively","Electron: −1|electron 1|negative|negatively","Neutron: 0 (no charge)|neutron 0|no charge|uncharged|zero"],
["E.2","Outline",2,"Outline the photoelectric effect.","Light above a threshold frequency ejects electrons from a metal surface|threshold|eject|emit|electrons","This shows light acts as photons: intensity changes the number of electrons, not their energy|photon|particle|intensity|number"],
["E.2","State",1,"State the equation for the energy of a photon.","E = hf|e hf|hf"],
["E.3","State",3,"State the three types of nuclear radiation and what each is.","Alpha: a helium nucleus|alpha helium|helium","Beta: a fast electron (or positron)|beta electron|electron","Gamma: electromagnetic radiation|gamma|electromagnetic|photon"],
["E.3","Define",1,"Define half-life.","The time taken for the number of undecayed nuclei (or the activity) to fall to 50%|50|halve|halves|halved|time taken|time for"],
["E.4","Outline",2,"Outline nuclear fission.","A heavy nucleus such as uranium-235 absorbs a neutron and splits|heavy|uranium|split|neutron","Into smaller nuclei, releasing energy and more neutrons (a chain reaction)|energy|chain reaction|more neutrons|smaller"],
["E.4","State",2,"State the role of the moderator and of the control rods in a reactor.","The moderator slows down neutrons|moderator|slow","Control rods absorb neutrons to control the rate|control rod|absorb"],
["E.5","Outline",2,"Outline why fusion needs very high temperatures.","Nuclei are positive and repel each other|repel|positive|electrostatic","High temperatures give them enough kinetic energy to get close enough to fuse|kinetic energy|fast|close|overcome"],
["E.5","State",1,"State the main fusion process in main-sequence stars.","Hydrogen fuses into helium|hydrogen helium|helium hydrogen"],
]);

/* ---------- more questions, each with a model answer and an examiner's tip ---------- */
QB("phys", [
["A.1","Calculate",2,"A ball is dropped from rest and falls for 3.0 s. Calculate the distance it falls (g = 9.8 m s⁻²).","Uses s = ut + ½at² with u = 0|ut|half|s ut","s = 44 m (44.1 m)|44|44.1",{model:"s = ut + ½at² = 0 + ½ × 9.8 × 3.0² = 44.1 m (44 m).",tip:"Write the equation first: the method mark is safe even if you slip."}],
["A.1","Outline",2,"Outline what the gradient and the area under a velocity–time graph represent.","The gradient is the acceleration|acceleration","The area under the graph is the displacement|displacement|distance",{model:"The gradient of a velocity–time graph is the acceleration, and the area under it is the displacement.",tip:"Gradient and area, one meaning each."}],
["A.2","State",2,"State Newton's third law.","When body A exerts a force on body B, B exerts an equal force on A|equal","In the opposite direction, and of the same type|opposite",{model:"If body A exerts a force on body B, then B exerts a force of equal size on A, in the opposite direction and of the same type.",tip:"The two forces act on different bodies."}],
["A.2","Calculate",1,"Calculate the force needed to accelerate a 1500 kg car at 2.0 m s⁻².","3000 N|3000|3.0 10 3",{model:"F = ma = 1500 × 2.0 = 3000 N.",tip:"F = ma, with the unit N."}],
["A.3","Calculate",1,"Calculate the gain in gravitational potential energy when a 50 kg student climbs 3.0 m (g = 9.8 N kg⁻¹).","1470 J|1470|1500 j|1.5 kj",{model:"ΔEp = mgΔh = 50 × 9.8 × 3.0 = 1470 J.",tip:"mgh, then units: J."}],
["A.3","Define",2,"Define efficiency.","Useful energy (or power) output divided by the total energy (or power) input|useful|output","Often given as a percentage|percentage|100|total input|input",{model:"Efficiency = useful energy output ÷ total energy input, often multiplied by 100 to give a percentage.",tip:"'Useful' and 'total' are both needed."}],
["A.4","Define",2,"Define moment of inertia.","A measure of a body's resistance to angular acceleration|resistance|angular acceleration|resists|rotational","It depends on the mass and how it is distributed about the axis (I = Σmr²)|distribution|distributed|axis|mr2",{model:"Moment of inertia measures how strongly a body resists angular acceleration. It depends on its mass and how that mass is distributed about the axis of rotation (I = Σmr²).",tip:"It is the rotational version of mass."}],
["A.4","State",2,"State the principle of conservation of angular momentum.","The total angular momentum of a system stays constant|constant|stays the same|unchanged","Provided no external torque acts on it|no external torque|external torque|no torque|resultant torque",{model:"The total angular momentum of a system stays constant, provided no external torque acts on it.",tip:"The condition (no external torque) is half the marks."}],
["A.5","Outline",2,"Outline length contraction.","A moving object is measured to be shorter along its direction of motion|shorter|reduced","Than its proper length, measured in its own rest frame (L = L₀ / γ)|proper length|rest frame|at rest|gamma|lorentz",{model:"An observer measures a moving object to be shorter along its direction of motion than its proper length, which is measured in the object's rest frame: L = L₀ / γ.",tip:"Use the term proper length."}],
["A.5","Outline",2,"Outline what Galilean relativity assumes that special relativity rejects.","Time is absolute: it passes at the same rate for all observers|time is absolute|absolute time|same for all","Velocities simply add, so the measured speed of light would depend on the observer|velocities add|speed of light|add",{model:"Galilean relativity assumes time is absolute, the same for every observer, and that velocities simply add. Special relativity rejects both: the speed of light is the same for all observers, so time must vary.",tip:"Absolute time and simple velocity addition are the two assumptions."}],
["B.1","Define",2,"Define specific latent heat of fusion.","The energy needed to change 1 kg of a substance from solid to liquid|solid to liquid|melt|melting","At constant temperature|constant temperature|without a change in temperature|same temperature",{model:"Specific latent heat of fusion is the energy needed to change 1 kg of a substance from solid to liquid without any change in temperature.",tip:"Include per kilogram and constant temperature."}],
["B.1","Outline",2,"Outline how energy is transferred by convection.","Fluid near the heat source expands, becomes less dense and rises|less dense|rises|expands","Cooler, denser fluid sinks to replace it, setting up a current|sinks|denser|current|circulation",{model:"Fluid near the heat source expands, becomes less dense and rises. Cooler, denser fluid sinks to take its place, setting up a convection current.",tip:"Explain it through density changes."}],
["B.2","State",2,"State the Stefan–Boltzmann law.","The power radiated is proportional to the surface area and to the fourth power of the temperature (P = eσAT⁴)|t4|t 4|fourth power","For a black body; real bodies include their emissivity e|black body|emissivity|blackbody",{model:"The power radiated by a black body is proportional to its surface area and to the fourth power of its absolute temperature: P = σAT⁴ (P = eσAT⁴ for a real body with emissivity e).",tip:"The T⁴ dependence is the heart of it."}],
["B.2","Outline",2,"Outline why the Earth's equilibrium temperature depends on its albedo.","Albedo is the fraction of incoming radiation that is reflected|fraction|reflected|reflects","A higher albedo means less energy is absorbed, so absorbed and emitted power balance at a lower temperature|less absorbed|lower temperature|balance|cooler|absorbed equals emitted",{model:"Albedo is the fraction of incoming radiation that is reflected. A higher albedo means less energy is absorbed, so the balance between absorbed and emitted power is reached at a lower temperature.",tip:"Define albedo, then link it to energy balance."}],
["B.3","State",1,"A fixed mass of gas at 300 K is heated to 600 K at constant volume. State what happens to its pressure.","It doubles|doubles|double|twice",{model:"The pressure doubles, because pressure is proportional to kelvin temperature at constant volume.",tip:"Always use kelvin in gas law questions."}],
["B.3","Explain",2,"Explain, using the kinetic model, why the pressure of a gas rises when its temperature rises at constant volume.","The molecules move faster, with a higher average kinetic energy|faster|kinetic energy","So they hit the walls more often and with a greater change in momentum (force)|more often|more frequent|greater force|harder|momentum",{model:"At a higher temperature the molecules move faster, so they hit the container walls more often and with a greater change in momentum each time, giving a larger force per unit area.",tip:"Two effects: more frequent and harder collisions."}],
["B.4","Define",2,"Define the efficiency of a heat engine and state why it is always less than 100%.","Useful work done divided by the heat supplied|work done|heat supplied|useful work","Some heat must always be transferred to the cold reservoir (second law of thermodynamics)|cold reservoir|second law|exhaust|heat lost",{model:"Efficiency = useful work done ÷ heat supplied. It is always less than 100% because, by the second law, some heat must always be transferred to the cold reservoir.",tip:"Quote the second law."}],
["B.4","Outline",2,"Outline what happens in an isothermal process for an ideal gas.","The temperature stays constant, so the internal energy does not change|constant temperature|temperature constant|internal energy","So the heat supplied equals the work done by the gas (Q = W)|heat equals work|work done",{model:"In an isothermal process the temperature stays constant, so the internal energy of an ideal gas does not change, and any heat supplied equals the work done by the gas.",tip:"Use the first law: ΔU = 0, so Q = W."}],
["B.5","Calculate",1,"Calculate the total resistance of a 4.0 Ω resistor and a 12 Ω resistor connected in parallel.","3.0 Ω|3|3.0",{model:"1/R = 1/4.0 + 1/12 = 4/12, so R = 3.0 Ω.",tip:"In parallel, the total is less than the smallest resistor."}],
["B.5","Define",2,"Define electromotive force (emf).","The energy transferred per unit charge|per unit charge|per coulomb|energy per charge","By the source, into electrical energy, as charge passes through it|source|cell|battery|converted|chemical",{model:"The emf is the energy transferred by a source into electrical energy per unit charge passing through it.",tip:"It is energy per charge, not a force."}],
["C.1","Outline",2,"Outline the energy changes during one oscillation of a simple pendulum.","Kinetic energy is greatest at the lowest (equilibrium) point|kinetic|lowest point|equilibrium|centre","Potential energy is greatest at the extremes, and the total energy stays constant|potential|extremes|maximum displacement|top|total",{model:"The kinetic energy is greatest at the lowest, equilibrium point, and the potential energy is greatest at the extremes of the swing. Energy changes between the two while the total stays constant (ignoring friction).",tip:"Say where each energy is at its maximum."}],
["C.1","Define",2,"Define the period of an oscillation.","The time for one complete oscillation|time|one complete|one full","T = 1/f, the reciprocal of the frequency|reciprocal|1 f|frequency",{model:"The period is the time for one complete oscillation; it is the reciprocal of the frequency, T = 1/f.",tip:"Link it to frequency."}],
["C.2","Define",2,"Define the amplitude of a wave.","The maximum displacement|maximum displacement|maximum","From the equilibrium (rest) position|equilibrium|rest position|undisturbed",{model:"The amplitude is the maximum displacement of a particle from its equilibrium position.",tip:"Displacement, from equilibrium."}],
["C.2","Outline",2,"Outline two differences between sound waves and light waves.","Sound is longitudinal; light is transverse|longitudinal|transverse","Sound needs a medium; light (electromagnetic) can travel through a vacuum|medium|vacuum|electromagnetic","Light travels much faster|faster|speed",{model:"Sound is a longitudinal wave that needs a medium, while light is a transverse electromagnetic wave that can travel through a vacuum.",tip:"Two clear contrasts, each with both sides."}],
["C.3","Calculate",1,"Light enters glass from air at an angle of incidence of 40° and refracts at 25°. Calculate the refractive index of the glass.","n = 1.52|1.52|1.5",{model:"n = sin 40° ÷ sin 25° = 0.643 ÷ 0.423 = 1.52.",tip:"Snell's law, with the angles measured from the normal."}],
["C.3","Outline",2,"Outline the conditions needed for two-source interference to give a stable pattern.","The sources must be coherent, with a constant phase difference|coherent|constant phase","And have the same frequency, with similar amplitudes|same frequency|same wavelength|similar amplitude",{model:"The two sources must be coherent, with a constant phase difference, and have the same frequency (and similar amplitudes for clear fringes).",tip:"Coherence is the key word."}],
["C.4","State",1,"State the wavelength of the first harmonic on a string of length L fixed at both ends.","λ = 2L|2l|2 l|twice the length",{model:"λ = 2L: the first harmonic is half a wavelength, with a node at each end.",tip:"Sketch the wave: one loop is half a wavelength."}],
["C.4","Outline",2,"Outline how a standing wave forms.","Two waves of the same frequency and amplitude travel in opposite directions, e.g. by reflection|opposite directions|reflected|reflection","They superpose, forming nodes and antinodes|superpose|superposition|interfere|nodes|antinodes",{model:"A wave and its reflection, with the same frequency and amplitude, travel in opposite directions and superpose, forming fixed nodes and antinodes.",tip:"Mention the reflection and the superposition."}],
["C.5","Explain",2,"Explain why an approaching ambulance's siren sounds higher-pitched.","The source moves towards the observer, so the wavefronts are compressed and the wavelength shorter|compressed|closer together|shorter wavelength|bunched","So the observed frequency is higher|higher frequency|frequency increases|more waves per second",{model:"As the ambulance moves towards you, each wavefront is emitted closer to the last, so the wavelength reaching you is shorter and the frequency you hear is higher.",tip:"Pitch means frequency: say so."}],
["C.5","Outline",2,"Outline how the Doppler effect can be used to measure the speed of blood flow.","Ultrasound is reflected off the moving blood cells|reflected|reflect|bounced","The change in frequency of the reflected wave is measured and used to calculate the speed|change in frequency|frequency shift|shift|compared",{model:"Ultrasound is reflected off the moving blood cells; the change in frequency of the reflected wave is measured and used to calculate the speed of flow.",tip:"Reflection, then the frequency shift."}],
["D.1","Calculate",1,"Calculate the gravitational field strength at the surface of a planet of mass 6.0 × 10²⁴ kg and radius 6.4 × 10⁶ m (G = 6.67 × 10⁻¹¹ N m² kg⁻²).","g = 9.8 N kg⁻¹|9.8|9.77|9.7",{model:"g = GM / r² = (6.67 × 10⁻¹¹ × 6.0 × 10²⁴) ÷ (6.4 × 10⁶)² = 9.8 N kg⁻¹.",tip:"Square the radius; it's the most common slip."}],
["D.1","Outline",2,"Outline why astronauts in orbit feel weightless.","They and their spacecraft are in free fall together|free fall|freefall|falling","So there is no contact force between them, even though gravity still acts|no contact force|no normal force|no reaction|gravity still|still gravity",{model:"The astronauts and the spacecraft are falling around the Earth together (free fall), so there is no contact force between them, which is what we feel as weight. Gravity still acts on them.",tip:"Gravity has not disappeared: say so."}],
["D.2","Calculate",1,"Calculate the force between two charges of 1.0 μC that are 0.10 m apart (k = 8.99 × 10⁹ N m² C⁻²).","F = 0.899 N|0.899|0.90",{model:"F = kq₁q₂ / r² = 8.99 × 10⁹ × (1.0 × 10⁻⁶)² ÷ 0.10² = 0.899 N.",tip:"Convert μC to C (× 10⁻⁶) before substituting."}],
["D.2","State",2,"State one similarity and one difference between gravitational and electric fields.","Both follow an inverse-square law with distance|inverse square|both","Gravity only attracts; electric forces can attract or repel|always attractive|attract or repel|repel|repulsive",{model:"Both fields follow an inverse-square law with distance. But gravitational forces are always attractive, while electric forces can attract or repel.",tip:"One similarity and one difference, clearly labelled."}],
["D.3","Calculate",2,"An electron (m = 9.11 × 10⁻³¹ kg, q = 1.6 × 10⁻¹⁹ C) moves at 2.0 × 10⁶ m s⁻¹ at right angles to a 0.010 T field. Calculate the radius of its path.","Uses r = mv / qB|mv qb|mv|qb","r = 1.1 × 10⁻³ m (1.14 mm)|1.14|0.00114",{model:"r = mv / qB = (9.11 × 10⁻³¹ × 2.0 × 10⁶) ÷ (1.6 × 10⁻¹⁹ × 0.010) = 1.14 × 10⁻³ m.",tip:"Set the magnetic force equal to the centripetal force to get r = mv/qB."}],
["D.3","Explain",2,"Explain why a magnetic field does no work on a moving charged particle.","The magnetic force is always perpendicular to the velocity|perpendicular|right angles|90","So the speed and kinetic energy stay the same; only the direction changes|speed constant|kinetic energy constant|direction|no change in speed",{model:"The magnetic force is always perpendicular to the particle's velocity, so it has no component along the motion: it changes the direction but not the speed, so no work is done.",tip:"Work needs a force component along the motion."}],
["D.4","Define",2,"Define magnetic flux.","Φ = BA cos θ|ba|cos","The field strength multiplied by the area perpendicular to the field|area|perpendicular|multiplied",{model:"Magnetic flux is the magnetic field strength multiplied by the area perpendicular to the field: Φ = BA cos θ.",tip:"Give the equation and what each part means."}],
["D.4","Outline",2,"Outline how a transformer changes the voltage of an alternating supply.","The current in the primary coil creates a changing magnetic flux in the iron core|changing flux|changing magnetic|iron core|core","Which induces an emf in the secondary coil, with Vs / Vp = Ns / Np|induces|induced|turns ratio|number of turns",{model:"The alternating current in the primary coil creates a changing magnetic flux in the iron core. This changing flux induces an emf in the secondary coil, with Vs / Vp = Ns / Np.",tip:"The flux must be changing: that's why it needs AC."}],
["E.1","State",2,"State what the line spectrum of hydrogen shows about atoms.","Electrons occupy discrete (quantized) energy levels|discrete|energy levels|quantised|quantized","Photons of specific energies are emitted when electrons fall between levels|specific|particular|transition|fall|drop",{model:"The line spectrum shows that electrons occupy discrete energy levels: each line is a photon of a specific energy, emitted when an electron falls between two levels.",tip:"Discrete energy levels is the key conclusion."}],
["E.1","Calculate",1,"Calculate the number of neutrons in a nucleus of uranium-238 (Z = 92).","146|146",{model:"Neutrons = 238 − 92 = 146.",tip:"Mass number minus proton number."}],
["E.2","Explain",2,"Explain why the photoelectric effect supports the photon model of light.","Emission depends on frequency, not intensity, with a threshold frequency|threshold|threshold frequency|not intensity","Each photon gives its energy hf to one electron, so below the work function no electrons are emitted|one electron|single electron|work function|hf",{model:"No electrons are emitted below a threshold frequency, however intense the light. This fits photons: each gives its energy hf to one electron, so if hf is below the work function, no electron escapes.",tip:"The threshold frequency is the evidence waves can't explain."}],
["E.2","State",2,"State de Broglie's hypothesis.","Particles of matter have wave properties|wave|waves|wavelike","With a wavelength λ = h / p|planck|momentum|h p",{model:"All moving particles have wave properties, with a de Broglie wavelength λ = h / p, where p is the momentum.",tip:"Give the equation."}],
["E.3","Calculate",1,"A sample has a half-life of 8 days. Calculate the fraction remaining after 24 days.","1/8 (12.5%)|1 8|12.5|0.125",{model:"24 days is 3 half-lives, so the fraction remaining is (½)³ = 1/8.",tip:"Count the half-lives first."}],
["E.3","Outline",2,"Outline why alpha radiation is the most ionizing but the least penetrating.","Alpha particles have a large charge and mass|charge|large mass|heavy","So they interact strongly with matter, lose energy quickly and are stopped by paper|stopped by paper|paper|few cm|lose energy quickly|strongly",{model:"Alpha particles have a large charge (+2) and mass, so they interact strongly with atoms, ionizing many of them, and lose their energy quickly: a sheet of paper stops them.",tip:"Strong ionization is why penetration is low: link the two."}],
["E.4","Explain",2,"Explain why a chain reaction can occur in uranium-235.","Each fission releases two or three neutrons|neutrons|two or three","Which can cause further fissions if there is enough material (critical mass)|further fission|more fissions|critical mass|critical",{model:"Each fission of U-235 releases two or three neutrons, which can be absorbed by other U-235 nuclei and cause further fissions, as long as there is at least a critical mass.",tip:"Mention the neutrons released and the critical mass."}],
["E.4","Outline",2,"Outline why fission releases energy, in terms of binding energy.","The products have a higher binding energy per nucleon than uranium|per nucleon|higher binding|more tightly bound","The difference appears as a mass defect released as energy, E = mc²|mass defect|mc2|mass lost",{model:"The fission products have a higher binding energy per nucleon than uranium, so their total mass is less. This mass difference is released as energy, E = mc².",tip:"Per nucleon is the vital phrase."}],
["E.5","Outline",2,"Outline how a star's mass determines its final stage.","Low- and medium-mass stars become white dwarfs|white dwarf","High-mass stars explode as supernovae, leaving neutron stars or black holes|neutron star|black hole|supernova",{model:"Stars like the Sun end as white dwarfs. Much more massive stars explode as supernovae, leaving a neutron star or, for the largest, a black hole.",tip:"Give the outcome for both low and high mass."}],
["E.5","Outline",2,"Outline what a Hertzsprung–Russell (HR) diagram shows.","Stars' luminosity plotted against their surface temperature|luminosity|temperature","Stars fall into groups such as the main sequence, giants and white dwarfs|main sequence|giants|white dwarfs|groups",{model:"An HR diagram plots stars' luminosity against their surface temperature. Stars fall into groups: the main sequence, red giants and supergiants, and white dwarfs.",tip:"Name the axes, then the groups."}],
]);

/* ---------- a second set: every topic now has at least eight questions ---------- */
QB("phys", [
["A.1","Define",2,"Define acceleration.","The rate of change of velocity|rate of change|change in velocity per unit time|per unit time","A vector quantity, measured in m s⁻²|vector|m s 2|ms 2",{model:"Acceleration is the rate of change of velocity; it is a vector measured in m s⁻².",tip:"Velocity, not speed."}],
["A.1","Calculate",2,"A ball is thrown vertically upwards at 20 m s⁻¹. Calculate the maximum height it reaches (g = 9.8 m s⁻²).","Use v² = u² + 2as with v = 0 at the top|v2 u2 2as|u2 2g|400 19.6","h = 400 ÷ 19.6 = 20.4 m|20.4",{model:"At the top v = 0, so h = u² ÷ 2g = 400 ÷ 19.6 = 20.4 m.",tip:"v = 0 at the highest point."}],
["A.1","Distinguish",2,"Distinguish between speed and velocity.","Speed is a scalar: the rate of change of distance|scalar|magnitude only|no direction","Velocity is a vector: the rate of change of displacement, with a direction|vector|direction|displacement",{model:"Speed is a scalar (distance per unit time); velocity is a vector (displacement per unit time) and includes direction.",tip:"Scalar versus vector."}],
["A.1","Outline",2,"Outline the motion of a falling object as it reaches terminal velocity.","Air resistance increases with speed, so the resultant force and acceleration decrease|increases with speed|resultant force decreases|acceleration decreases|less acceleration","Until air resistance equals the weight: zero resultant force, so speed is constant|equals weight|equal to weight|equals the weight|balanced|zero acceleration|constant speed|no resultant",{model:"As speed increases, air resistance increases, so the resultant force and acceleration decrease until air resistance equals the weight; then acceleration is zero and the speed is constant.",tip:"Balanced forces, constant velocity."}],
["A.2","Define",2,"Define impulse.","The change in momentum|change in momentum|change of momentum","Equal to the force multiplied by the time it acts (FΔt)|force time|force multiplied by time|force x time|force times time",{model:"Impulse is the change in momentum, equal to the force multiplied by the time it acts (FΔt).",tip:"The area under a force–time graph."}],
["A.2","State",2,"State the law of conservation of linear momentum.","The total momentum of a system stays constant|total momentum|stays constant|remains constant|before equals after|same before and after","Provided no external resultant force acts|no external force|external|isolated|closed system",{model:"The total momentum of a system stays constant provided no external resultant force acts on it.",tip:"Isolated system is the condition."}],
["A.2","Calculate",2,"A 0.50 kg ball hits a wall at 4.0 m s⁻¹ and rebounds at 3.0 m s⁻¹. Calculate the magnitude of its change in momentum.","The velocity reverses, so Δv = 3.0 − (−4.0) = 7.0 m s⁻¹|7.0|7 m s","Δp = 0.50 × 7.0 = 3.5 kg m s⁻¹|3.5",{model:"The direction reverses, so Δv = 7.0 m s⁻¹ and Δp = 0.50 × 7.0 = 3.5 kg m s⁻¹.",tip:"Take one direction as positive."}],
["A.2","Outline",2,"Outline why a seatbelt reduces injury in a crash.","It increases the time over which the person stops|increases the time|longer time|more time","So the force is smaller for the same change in momentum|smaller force|less force|reduces the force|force is reduced|lower force",{model:"A seatbelt stretches, increasing the time taken to stop, so the force is smaller for the same change in momentum.",tip:"F = Δp ÷ Δt."}],
["A.3","State",2,"State the principle of conservation of energy.","Energy cannot be created or destroyed|created|destroyed","It is only transferred between forms; the total energy of an isolated system stays constant|transferred|transformed|changes form|total energy",{model:"Energy can't be created or destroyed, only transferred from one form to another, so the total energy of an isolated system is constant.",tip:"Learn the wording."}],
["A.3","Calculate",2,"A motor lifts a 20 kg load through 3.0 m in 4.0 s. Calculate its useful power output (g = 9.8 m s⁻²).","Work done = mgh = 20 × 9.8 × 3.0 = 588 J|588","P = 588 ÷ 4.0 = 147 W|147",{model:"Work = mgh = 20 × 9.8 × 3.0 = 588 J; P = 588 ÷ 4.0 = 147 W.",tip:"Power = work ÷ time."}],
["A.3","Define",2,"Define work done by a force.","The product of the force and the displacement|force displacement|force distance|force times|force multiplied","In the direction of the force|in the direction|same direction|direction of the force|cos",{model:"Work done is the product of the force and the displacement in the direction of the force.",tip:"W = Fs cos θ."}],
["A.3","Calculate",1,"A motor uses 500 J of electrical energy and does 350 J of useful work. Calculate its efficiency.","70% (0.70)|70|0.70",{model:"Efficiency = 350 ÷ 500 = 0.70 = 70%.",tip:"Useful out ÷ total in."}],
["A.4","Calculate",1,"Calculate the torque from a 20 N force acting at right angles to a spanner 0.25 m from the pivot.","5.0 N m|5.0 n m|5 n m|5 nm|5.0 nm",{model:"Torque = Fr = 20 × 0.25 = 5.0 N m.",tip:"Perpendicular distance from the pivot."}],
["A.4","Explain",2,"Explain why a spinning skater rotates faster after pulling their arms in.","Pulling the arms in reduces the moment of inertia|moment of inertia|reduces|smaller i","Angular momentum is conserved, so the angular velocity increases|angular momentum|conserved|angular velocity increases|spins faster",{model:"Pulling the arms in reduces the moment of inertia; angular momentum Iω is conserved, so ω increases.",tip:"L = Iω."}],
["A.4","Define",2,"Define angular velocity.","The rate of change of angular displacement|rate of change of angle|angle per unit time|angular displacement|angle turned","Measured in rad s⁻¹|rad s 1|radians per second|rad",{model:"Angular velocity is the rate of change of angular displacement, in rad s⁻¹.",tip:"ω = 2π ÷ T."}],
["A.4","Calculate",1,"Calculate the rotational kinetic energy of a wheel with I = 0.40 kg m² spinning at 10 rad s⁻¹.","½ × 0.40 × 10² = 20 J|20",{model:"Ek = ½Iω² = 0.5 × 0.40 × 100 = 20 J.",tip:"The rotational form of ½mv²."}],
["A.5","Define",2,"Define proper time.","The time interval between two events measured by an observer|time interval|observer|frame","For whom both events happen at the same place|same place|same position|same location|at rest",{model:"Proper time is the time interval between two events measured in the frame where both events occur at the same place.",tip:"Proper time is always the shortest."}],
["A.5","Calculate",2,"Calculate the Lorentz factor for a speed of 0.60c.","γ = 1 ÷ √(1 − 0.36)|0.36|0.8|0.80","= 1.25|1.25",{model:"γ = 1 ÷ √(1 − 0.60²) = 1 ÷ √0.64 = 1 ÷ 0.80 = 1.25.",tip:"Square v/c first."}],
["A.5","Outline",2,"Outline the relativity of simultaneity.","Two events that happen at the same time in one frame|one frame|one observer|same time","May happen at different times in another frame moving relative to the first|different times|another frame|other frame|moving observer",{model:"Two events that are simultaneous in one frame may happen at different times in another frame moving relative to it.",tip:"Time isn't absolute."}],
["A.5","State",1,"State why an object with mass can never reach the speed of light.","Its energy (and γ) would become infinite, so infinite work would be needed|infinite|infinity|unlimited energy",{model:"As v approaches c, γ and the energy needed approach infinity, so infinite work would be required.",tip:"γ → ∞ as v → c."}],
["B.1","Calculate",2,"Calculate the energy needed to melt 0.50 kg of ice at 0 °C (L = 3.3 × 10⁵ J kg⁻¹).","Q = mL|q ml|mass latent","= 1.65 × 10⁵ J (1.7 × 10⁵ J)|1.65|1.7 10 5|165000",{model:"Q = mL = 0.50 × 3.3 × 10⁵ = 1.65 × 10⁵ J.",tip:"No temperature change, so no ΔT."}],
["B.1","Outline",2,"Outline how energy is transferred by conduction in a metal.","Vibrating ions pass energy to neighbouring ions|vibrate|vibrations|vibrating|neighbouring|neighboring","Free (delocalized) electrons carry energy quickly through the metal|free electrons|delocalized|delocalised|electrons",{model:"Vibrating ions pass energy to their neighbours, and free electrons move through the metal carrying energy quickly.",tip:"Electrons make metals good conductors."}],
["B.1","Explain",2,"Explain why the temperature of a substance stays constant while it boils.","Energy is used to overcome intermolecular forces, increasing potential energy|overcome|intermolecular|potential energy|separate",{model:"The energy supplied overcomes the intermolecular forces, increasing potential energy, not average kinetic energy, so temperature stays constant.",tip:"Temperature tracks kinetic energy."},"Not to increase the average kinetic energy of the particles|kinetic|not increase|average kinetic"],
["B.1","State",2,"State Wien's displacement law.","The peak wavelength is inversely proportional to absolute temperature|inversely proportional|inversely|inverse","λmax T = 2.9 × 10⁻³ m K|2.9 10 3|peak wavelength|max t",{model:"The wavelength of peak emission is inversely proportional to absolute temperature: λmax T = 2.9 × 10⁻³ m K.",tip:"Hotter stars look bluer."}],
["B.2","Define",2,"Define emissivity.","The ratio of the power radiated by a surface|ratio|power radiated|radiated power","To the power radiated by a black body at the same temperature|black body|blackbody",{model:"Emissivity is the ratio of the power radiated by a surface to the power radiated by a black body at the same temperature.",tip:"Between 0 and 1."}],
["B.2","Outline",2,"Outline why greenhouse gases absorb infrared radiation.","Infrared frequencies match the natural frequencies of the molecules' vibrations|natural frequency|natural frequencies|resonance|vibrate|vibrations","So molecules such as CO₂ and H₂O absorb it and re-emit it in all directions|re emit|all directions|reradiate|co2|water vapour|methane",{model:"Infrared frequencies match the natural vibration frequencies of molecules such as CO₂ and H₂O, so they absorb it (resonance) and re-emit it in all directions, some back to Earth.",tip:"Resonance is the key idea."}],
["B.2","Outline",2,"Outline one positive feedback that increases global warming.","Melting ice reduces albedo, or thawing permafrost releases methane|albedo|melting ice|ice melts|permafrost|methane|water vapour","So more energy is absorbed and warming increases further|further warming|more warming|amplifies|more absorbed|absorbs more",{model:"Warming melts ice, lowering the albedo, so more radiation is absorbed and the warming increases further.",tip:"Feedback: the effect strengthens the cause."}],
["B.2","Calculate",2,"Calculate the power radiated by a black body of surface area 2.0 m² at 300 K (σ = 5.67 × 10⁻⁸ W m⁻² K⁻⁴).","P = σAT⁴, with T⁴ = 8.1 × 10⁹|8.1 10 9|t4|σat4","= 918 W (about 920 W)|918|920|919",{model:"P = σAT⁴ = 5.67 × 10⁻⁸ × 2.0 × (300)⁴ = 918 W.",tip:"Raise T to the fourth power."}],
["B.3","Define",2,"Define an ideal gas.","A gas that obeys pV = nRT exactly|pv nrt|obeys|all pressures","Its particles have negligible volume and no intermolecular forces except during collisions|negligible volume|no intermolecular|no forces|elastic",{model:"An ideal gas obeys pV = nRT exactly; its particles have negligible volume and no intermolecular forces except during collisions.",tip:"Real gases approximate it."}],
["B.3","Calculate",1,"A gas at 100 kPa has its volume halved at constant temperature. Calculate its new pressure.","200 kPa (pressure doubles)|200",{model:"pV is constant, so halving V doubles p: 200 kPa.",tip:"Boyle's law."}],
["B.3","Outline",2,"Outline what is meant by absolute zero.","The lowest possible temperature, 0 K (−273 °C)|0 k|273|lowest|zero kelvin","Where the particles have the minimum possible kinetic energy|minimum kinetic energy|minimum energy|no kinetic|stop moving|least energy",{model:"Absolute zero (0 K, −273 °C) is the lowest possible temperature, where particles have minimum kinetic energy.",tip:"The zero of the kelvin scale."}],
["B.3","State",2,"State the relationship between the average kinetic energy of gas particles and temperature.","Average kinetic energy is directly proportional|proportional|directly proportional","To the absolute (kelvin) temperature: Ek = 3/2 kT|kelvin|absolute|3 2 kt",{model:"The average kinetic energy of the particles is directly proportional to absolute temperature: Ek = 3/2 kT.",tip:"Kelvin only."}],
["B.4","Outline",2,"Outline what happens in an adiabatic process.","No thermal energy is transferred to or from the gas (Q = 0)|no thermal energy|no heat|q 0|no energy transferred","So work done on or by the gas changes its internal energy and temperature|temperature changes|internal energy|temperature rises|temperature falls",{model:"In an adiabatic process no thermal energy is transferred (Q = 0), so work done changes the internal energy and temperature.",tip:"Compare with isothermal."}],
["B.4","Calculate",1,"Calculate the maximum (Carnot) efficiency of an engine working between 600 K and 300 K.","1 − 300 ÷ 600 = 0.50 (50%)|50",{model:"η = 1 − Tc ÷ Th = 1 − 300 ÷ 600 = 0.50.",tip:"Temperatures in kelvin."}],
["B.4","Outline",2,"Outline why thermal energy can't flow spontaneously from a cold body to a hot body.","It would decrease the total entropy|decrease entropy|entropy decrease|total entropy|entropy would fall","The second law says the entropy of an isolated system never decreases|second law|never decreases|always increases",{model:"Such a flow would decrease the total entropy, but the second law says the entropy of an isolated system never decreases.",tip:"A fridge needs work input."}],
["B.4","Calculate",1,"Calculate the work done by a gas expanding by 0.020 m³ at a constant pressure of 1.5 × 10⁵ Pa.","W = pΔV = 3000 J|3000|3.0 103|3 103|3 x 10 3|3.0 x 10 3|3 kj|3.0 kj",{model:"W = pΔV = 1.5 × 10⁵ × 0.020 = 3.0 × 10³ J.",tip:"Only at constant pressure."}],
["B.5","Define",2,"Define resistance.","The ratio of the potential difference across a component|potential difference|pd|voltage","To the current through it (R = V ÷ I)|current|v i|v over i",{model:"Resistance is the ratio of the potential difference across a component to the current through it, R = V ÷ I.",tip:"Unit: ohm."}],
["B.5","Calculate",1,"Calculate the power dissipated in a 10 Ω resistor carrying a current of 2.0 A.","P = I²R = 40 W|40",{model:"P = I²R = 2.0² × 10 = 40 W.",tip:"Three power formulas: VI, I²R, V²/R."}],
["B.5","Outline",2,"Outline how and why the resistance of a filament lamp changes with current.","Resistance increases as the current increases|increases|higher|goes up","The filament gets hotter, so ions vibrate more and collide more with electrons|heats|hotter|temperature|vibrate|collisions",{model:"As current increases, the filament gets hotter; the ions vibrate more and electrons collide with them more often, so resistance increases.",tip:"Non-ohmic: the I–V graph curves."}],
["B.5","Distinguish",2,"Distinguish between current in series and parallel circuits.","In series the current is the same everywhere|same everywhere|same current|same through","In parallel the current splits, and the branch currents add up to the total|splits|divides|shared|sum|add up",{model:"In series the current is the same everywhere; in parallel it splits between branches, and the branch currents add up to the total.",tip:"Kirchhoff's first law."}],
["C.1","Calculate",1,"Calculate the period of a simple pendulum of length 0.50 m (g = 9.81 m s⁻²).","T = 2π√(0.50 ÷ 9.81) = 1.42 s|1.42|1.4",{model:"T = 2π√(L ÷ g) = 2π√(0.50 ÷ 9.81) = 1.42 s.",tip:"Mass doesn't matter."}],
["C.1","Define",2,"Define the frequency of an oscillation.","The number of oscillations per unit time|number of oscillations|per second|per unit time|oscillations per","Measured in hertz; f = 1 ÷ T|hertz|hz|1 t",{model:"Frequency is the number of oscillations per unit time, in hertz; f = 1 ÷ T.",tip:"Frequency and period are reciprocals."}],
["C.1","State",2,"State where in its swing a pendulum has its maximum speed and its maximum acceleration.","Maximum speed at the equilibrium (centre) position|centre|center|equilibrium|middle|lowest point","Maximum acceleration at maximum displacement (the ends of the swing)|ends|extremes|maximum displacement|amplitude|turning points",{model:"Speed is greatest at the equilibrium position; acceleration is greatest at maximum displacement, at the ends of the swing.",tip:"a ∝ −x."}],
["C.1","State",1,"State the phase difference between displacement and velocity in simple harmonic motion.","π/2 rad (90°), a quarter of a cycle|90|quarter|pi 2",{model:"Velocity is π/2 rad (90°) out of phase with displacement.",tip:"Velocity is zero when displacement is maximum."}],
["C.2","Define",1,"Define wavelength.","The distance between two adjacent points in phase, e.g. crest to crest|crest to crest|peak to peak|adjacent crests|in phase|consecutive crests",{model:"Wavelength is the shortest distance between two points in phase, e.g. crest to crest.",tip:"Measured in metres."}],
["C.2","Calculate",1,"Calculate the period of a wave with frequency 250 Hz.","T = 1 ÷ 250 = 0.004 s|0.004|4.0 10 3|4 10 3|4 ms",{model:"T = 1 ÷ f = 1 ÷ 250 = 0.004 s (4 ms).",tip:"T = 1 ÷ f."}],
["C.2","Outline",2,"Outline what is meant by the intensity of a wave and how it depends on amplitude.","The power per unit area|power per unit area|per unit area|power area","Proportional to the amplitude squared (I ∝ A²)|amplitude squared|a2|squared|square",{model:"Intensity is the power per unit area, and it is proportional to amplitude squared.",tip:"Double the amplitude → four times the intensity."}],
["C.2","State",2,"State the speed of electromagnetic waves in a vacuum and one property all EM waves share.","3.00 × 10⁸ m s⁻¹|3 108|3.00 108|3 10 8|300000000|300 000 km","They are transverse, or need no medium|transverse|no medium|need a medium|oscillating electric and magnetic",{model:"All EM waves travel at 3.00 × 10⁸ m s⁻¹ in a vacuum and are transverse.",tip:"c = 3.00 × 10⁸ m s⁻¹."}],
["C.3","State",1,"State Snell's law.","n₁ sin θ₁ = n₂ sin θ₂|n1 sin|ratio of sines|sin i sin r",{model:"n₁ sin θ₁ = n₂ sin θ₂.",tip:"Angles from the normal."}],
["C.3","Define",2,"Define the critical angle.","The angle of incidence in the denser medium|angle of incidence|incidence|denser","For which the angle of refraction is 90°|90|along the boundary",{model:"The critical angle is the angle of incidence in the denser medium for which the angle of refraction is 90°.",tip:"sin c = 1 ÷ n."}],
["C.3","Outline",2,"Outline what happens when a wave passes through a gap similar in size to its wavelength.","It diffracts: it spreads out|spreads|diffracts|diffraction|bends","Its wavelength stays the same and the wavefronts become curved|wavelength unchanged|same wavelength|circular|curved",{model:"The wave diffracts, spreading out with curved wavefronts, while its wavelength stays the same.",tip:"Most diffraction when gap ≈ λ."}],
["C.3","Calculate",1,"Calculate the fringe spacing for light of wavelength 600 nm, slit separation 0.50 mm and screen distance 2.0 m.","s = λD ÷ d = 2.4 × 10⁻³ m (2.4 mm)|2.4|0.0024|2.4 10 3",{model:"s = λD ÷ d = (600 × 10⁻⁹ × 2.0) ÷ (0.50 × 10⁻³) = 2.4 × 10⁻³ m.",tip:"Convert nm and mm to metres."}],
["C.4","Outline",2,"Outline what is meant by damping.","Energy is lost from the oscillating system, e.g. to friction|energy lost|loses energy|friction|resistive","So the amplitude decreases over time|amplitude decreases|amplitude reduces|smaller amplitude|decreasing amplitude",{model:"Damping is the loss of energy from an oscillating system, e.g. through friction, so its amplitude decreases over time.",tip:"Light, critical and heavy damping."}],
["C.4","State",1,"A string's first harmonic is 110 Hz. State the frequency of its third harmonic.","330 Hz|330",{model:"The third harmonic is 3 × 110 = 330 Hz.",tip:"Harmonics are whole-number multiples."}],
["C.4","Distinguish",2,"Distinguish between a node and an antinode.","Node: a point of zero amplitude|zero amplitude|no displacement|no movement|stationary|zero displacement","Antinode: a point of maximum amplitude|maximum amplitude|maximum displacement|largest amplitude",{model:"A node is a point of zero amplitude; an antinode is a point of maximum amplitude.",tip:"Adjacent nodes are λ/2 apart."}],
["C.4","Outline",2,"Outline one useful example of resonance and one problem it causes.","Useful: musical instruments, microwave ovens or radio tuning|instruments|microwave|tuning|radio|mri","Problem: bridges, buildings or machine parts vibrating violently|bridge|bridges|buildings|tacoma|earthquake|engine|machinery",{model:"Resonance is useful in musical instruments and radio tuning, but it can make bridges and buildings vibrate dangerously.",tip:"One of each."}],
["C.5","Outline",2,"Outline what a blueshift indicates about a star.","The star is moving towards the observer|towards|approaching","So the received light has a shorter wavelength (higher frequency)|shorter wavelength|shorter|higher frequency|decreased wavelength",{model:"A blueshift means the star is moving towards us, so its light arrives with a shorter wavelength.",tip:"Redshift: moving away."}],
["C.5","Calculate",1,"A galaxy's light has a fractional redshift Δλ/λ = 0.010. Calculate its recession speed (c = 3.0 × 10⁸ m s⁻¹).","v = zc = 3.0 × 10⁶ m s⁻¹|3.0 106|3 106|3 10 6|3000000|3000 km",{model:"v = (Δλ/λ) × c = 0.010 × 3.0 × 10⁸ = 3.0 × 10⁶ m s⁻¹.",tip:"Valid when v ≪ c."}],
["C.5","Explain",2,"Explain why the observed frequency from a receding source is lower.","Each wavefront is emitted from further away, so wavefronts are spread out|further away|spread out|stretched|wavefronts","So the observed wavelength is longer|longer wavelength|longer|wavelength increases",{model:"Each wavefront is emitted from further away, so the wavefronts are spread out and the observed wavelength is longer.",tip:"Diagrams of wavefronts help."}],
["C.5","Outline",2,"Outline how a radar speed gun uses the Doppler effect.","Microwaves or radio waves are reflected from the moving vehicle|reflected|reflect|microwaves|radio waves","The frequency shift of the reflected waves gives the vehicle's speed|frequency shift|change in frequency|shift|frequency change",{model:"The gun sends microwaves that reflect off the moving vehicle; the frequency shift of the reflected waves gives its speed.",tip:"Same idea as blood-flow measurement."}],
["D.1","Define",2,"Define gravitational potential at a point.","The work done per unit mass|work done per unit mass|per unit mass|per kg","In bringing a small test mass from infinity to that point|infinity|from infinity",{model:"Gravitational potential is the work done per unit mass in bringing a small test mass from infinity to that point.",tip:"Always negative."}],
["D.1","Calculate",1,"Calculate the gravitational force between two 1000 kg masses 2.0 m apart (G = 6.67 × 10⁻¹¹ N m² kg⁻²).","F = Gm₁m₂ ÷ r² = 1.67 × 10⁻⁵ N|1.67 10 5|1.7 10 5|0.0000167",{model:"F = 6.67 × 10⁻¹¹ × 1000 × 1000 ÷ 2.0² = 1.67 × 10⁻⁵ N.",tip:"Square the distance."}],
["D.1","Explain",2,"Explain why a satellite in a circular orbit moves at constant speed.","Gravity acts towards the centre, at right angles to the velocity|perpendicular|right angles|towards the centre|centripetal","So it does no work and kinetic energy stays constant; only the direction changes|no work|kinetic energy constant|changes direction only|only direction",{model:"Gravity acts towards the centre, perpendicular to the velocity, so it does no work; the kinetic energy and speed stay constant and only the direction changes.",tip:"Perpendicular force, no work."}],
["D.1","State",2,"State Kepler's third law.","The square of a planet's orbital period is proportional to|square of the period|t2|period squared","The cube of its mean orbital radius|cube|r3|radius cubed",{model:"The square of the orbital period is proportional to the cube of the mean orbital radius: T² ∝ r³.",tip:"It follows from Newton's law of gravitation."}],
["D.2","Calculate",1,"Calculate the electric field strength between parallel plates 0.020 m apart with 500 V across them.","E = V ÷ d = 25 000 V m⁻¹|25000|2.5 104|2.5 10 4|25 000",{model:"E = V ÷ d = 500 ÷ 0.020 = 2.5 × 10⁴ V m⁻¹.",tip:"Uniform field."}],
["D.2","Describe",2,"Describe the electric field between two parallel charged plates.","Uniform: field lines equally spaced|uniform|equally spaced|evenly spaced|same strength","Directed from the positive plate to the negative plate|positive to negative|from positive|perpendicular to the plates",{model:"The field is uniform, with equally spaced lines running from the positive plate to the negative plate, perpendicular to the plates.",tip:"Edge effects aside."}],
["D.2","Outline",2,"Outline the shape and direction of the magnetic field around a straight current-carrying wire.","Concentric circles around the wire|concentric|circles|circular","Direction given by the right-hand grip rule|right hand|grip rule|right hand rule|corkscrew",{model:"The field lines are concentric circles around the wire, with direction given by the right-hand grip rule.",tip:"Thumb = current, fingers = field."}],
["D.2","State",1,"State the direction of the magnetic field lines outside a bar magnet.","From the north pole to the south pole|north to south|from north",{model:"Outside the magnet, field lines go from the north pole to the south pole.",tip:"Inside, they run south to north."}],
["D.3","Calculate",1,"Calculate the magnetic force on a 0.50 m wire carrying 3.0 A at right angles to a 0.20 T field.","F = BIL = 0.30 N|0.30",{model:"F = BIL = 0.20 × 3.0 × 0.50 = 0.30 N.",tip:"sin 90° = 1."}],
["D.3","Explain",2,"Explain why a charged particle moving parallel to a magnetic field experiences no force.","The force depends on the velocity component perpendicular to the field (F = qvB sin θ)|perpendicular component|sin θ|perpendicular","Here θ = 0, so sin θ = 0 and the force is zero|zero|sin 0|no perpendicular",{model:"F = qvB sin θ; moving parallel to the field, θ = 0, so sin θ = 0 and there is no force.",tip:"Only the perpendicular component counts."}],
["D.3","Outline",2,"Outline the motion of a charged particle in a uniform electric field.","It feels a constant force (F = qE)|constant force|qe|same force","So it accelerates uniformly, following a parabola if it enters across the field|accelerates|parabola|parabolic|curved path",{model:"The particle feels a constant force qE, so it accelerates uniformly; entering across the field, it follows a parabola.",tip:"Like a projectile."}],
["D.3","State",1,"State how the radius of a charged particle's circular path in a magnetic field changes when its speed increases by a factor of two.","The radius doubles (r = mv ÷ qB)|doubles|twice|doubled|2 times|x2",{model:"r = mv ÷ qB, so the radius doubles.",tip:"r ∝ v."}],
["D.4","Define",1,"Define magnetic flux linkage.","The magnetic flux through a coil multiplied by its number of turns (NΦ)|number of turns|turns",{model:"Flux linkage is the flux through a coil multiplied by its number of turns, NΦ.",tip:"Unit: Wb turns."}],
["D.4","Outline",2,"Outline why a transformer needs an alternating current.","An alternating current produces a changing magnetic flux in the core|changing flux|changing magnetic|varying flux|alternating flux","Which induces an emf in the secondary coil; a direct current gives a constant flux and no emf|induces|induced|secondary|no emf",{model:"Alternating current produces a changing flux in the core, inducing an emf in the secondary; direct current gives a constant flux, so no emf is induced.",tip:"Faraday's law needs change."}],
["D.4","Calculate",1,"Calculate the output voltage of a transformer with 100 primary turns, 500 secondary turns and a 12 V input.","Vs = 12 × 500 ÷ 100 = 60 V|60",{model:"Vs ÷ Vp = Ns ÷ Np, so Vs = 12 × 5 = 60 V.",tip:"Step-up transformer."}],
["D.4","Outline",2,"Outline how an AC generator produces an emf.","A coil rotates in a magnetic field|coil rotates|rotating coil|rotates|spins","The changing flux linkage induces an alternating emf|changing flux|flux linkage|induces|induced",{model:"A coil rotates in a magnetic field, so its flux linkage changes continuously, inducing an alternating emf.",tip:"Faster rotation: higher peak emf and frequency."}],
["E.1","Explain",2,"Explain why a few alpha particles were deflected through large angles in Rutherford's experiment.","The positive charge and mass are concentrated in a tiny nucleus|tiny nucleus|small nucleus|concentrated|dense","Alpha particles passing close to it were strongly repelled|repelled|repulsion|positive repels|like charges",{model:"The positive charge and mass are concentrated in a tiny nucleus; alpha particles passing very close are strongly repelled.",tip:"Most passed straight through: mostly empty space."}],
["E.1","Calculate",1,"Calculate the energy of the photon emitted when an electron in hydrogen falls from −3.4 eV to −13.6 eV.","10.2 eV|10.2 ev",{model:"E = −3.4 − (−13.6) = 10.2 eV.",tip:"The difference between levels."}],
["E.1","Outline",2,"Outline the Bohr model of the hydrogen atom.","Electrons orbit the nucleus only in fixed (discrete) energy levels|fixed|discrete|energy levels|orbits","They emit or absorb a photon when moving between levels|photon|emit|absorb|move between levels",{model:"Electrons occupy only fixed energy levels and emit or absorb a photon when moving between them.",tip:"Explains line spectra."}],
["E.1","State",2,"State the approximate radius of a nucleus and of an atom.","Nucleus: about 10⁻¹⁵ m|10 15|fm|femtometre","Atom: about 10⁻¹⁰ m|10 10|0.1 nm",{model:"A nucleus is about 10⁻¹⁵ m across and an atom about 10⁻¹⁰ m.",tip:"The atom is about 100 000 times bigger."}],
["E.2","Define",2,"Define work function.","The minimum energy needed|minimum energy|minimum","To remove an electron from the surface of a metal|remove an electron|release an electron|from the surface|free an electron",{model:"The work function is the minimum energy needed to remove an electron from the surface of a metal.",tip:"Threshold frequency = Φ ÷ h."}],
["E.2","Calculate",1,"Calculate the energy of a photon of frequency 5.0 × 10¹⁴ Hz (h = 6.63 × 10⁻³⁴ J s).","E = hf = 3.3 × 10⁻¹⁹ J|3.3 10 19|3.32 10 19|3.315",{model:"E = hf = 6.63 × 10⁻³⁴ × 5.0 × 10¹⁴ = 3.3 × 10⁻¹⁹ J.",tip:"Convert to eV by dividing by 1.6 × 10⁻¹⁹."}],
["E.2","Outline",2,"Outline the evidence from electron diffraction for the wave nature of matter.","Electrons passed through a thin crystal or graphite form a diffraction pattern of rings|diffraction pattern|rings|crystal|graphite","Diffraction is a wave property, so electrons behave as waves|wave property|behave as waves|wavelike|like waves",{model:"Electrons fired through graphite form a diffraction pattern of rings; diffraction is a wave property, so electrons behave as waves.",tip:"Evidence for de Broglie."}],
["E.2","Explain",2,"Explain why increasing light intensity doesn't increase the maximum kinetic energy of photoelectrons.","Higher intensity means more photons, not more energy per photon|number of photons|more photons","Each electron absorbs one photon, so the maximum kinetic energy depends only on frequency|one photon|depends on frequency|frequency|hf",{model:"Higher intensity gives more photons, not more energetic ones; each electron absorbs one photon, so maximum kinetic energy depends only on frequency.",tip:"Intensity changes the current."}],
["E.3","Define",2,"Define the activity of a radioactive sample.","The number of nuclei decaying per unit time|number of decays|decays per second|per unit time|decay per second","Measured in becquerels (Bq)|becquerel|becquerels|bq",{model:"Activity is the number of nuclei decaying per unit time, measured in becquerels.",tip:"1 Bq = one decay per second."}],
["E.3","State",2,"State the particles produced when a neutron undergoes beta-minus decay.","A proton and an electron|proton electron|proton and an electron","An antineutrino|antineutrino|anti neutrino",{model:"n → p + e⁻ + ν̄: a proton, an electron and an antineutrino.",tip:"Charge and lepton number are conserved."}],
["E.3","Outline",2,"Outline what background radiation is, with two sources.","Low-level radiation that is always present in the environment|always present|everywhere|environment|natural","From radon gas, rocks, cosmic rays, food or medical use|radon|rocks|cosmic|medical|soil|food",{model:"Background radiation is low-level radiation always present around us, from sources such as radon gas and cosmic rays.",tip:"Subtract it from measurements."}],
["E.3","Calculate",1,"A sample has a half-life of 6.0 hours. Calculate the time for its activity to fall to one-eighth.","Three half-lives = 18 hours|18",{model:"1/8 = (1/2)³, so 3 × 6.0 = 18 hours.",tip:"Count the halvings."}],
["E.4","Define",2,"Define nuclear binding energy.","The energy needed to separate a nucleus into its individual nucleons|separate|split|pull apart|individual nucleons|nucleons","Equivalent to the mass defect (E = mc²)|mass defect|released when formed|e mc2|mc2",{model:"Binding energy is the energy needed to separate a nucleus into its individual nucleons; it is equivalent to the mass defect.",tip:"Binding energy per nucleon shows stability."}],
["E.4","Outline",2,"Outline what is meant by critical mass.","The minimum mass of fissile material|minimum mass|minimum|least mass","Needed to sustain a chain reaction|sustain|chain reaction|self sustaining",{model:"Critical mass is the minimum mass of fissile material needed to sustain a chain reaction.",tip:"Below it, too many neutrons escape."}],
["E.4","Outline",2,"Outline one advantage and one disadvantage of nuclear power.","Advantage: no CO₂ emissions, high energy density, or reliable supply|no co2|low carbon|no carbon|high energy density|reliable","Disadvantage: long-lived radioactive waste or risk of accidents|radioactive waste|waste|accident|meltdown|chernobyl|fukushima",{model:"Nuclear power emits no CO₂ while running, but it produces long-lived radioactive waste.",tip:"One of each."}],
["E.4","Calculate",1,"Calculate the energy released when a mass of 3.0 × 10⁻²⁸ kg is converted to energy (c = 3.0 × 10⁸ m s⁻¹).","E = mc² = 2.7 × 10⁻¹¹ J|2.7 10 11",{model:"E = mc² = 3.0 × 10⁻²⁸ × (3.0 × 10⁸)² = 2.7 × 10⁻¹¹ J.",tip:"Square c."}],
["E.5","Outline",2,"Outline why a main-sequence star is stable.","Outward radiation and gas pressure from fusion|radiation pressure|gas pressure|outward pressure|fusion","Balance the inward pull of gravity (hydrostatic equilibrium)|balances|balance|gravity|gravitational|hydrostatic equilibrium",{model:"Outward radiation and gas pressure from fusion balance the inward pull of gravity: hydrostatic equilibrium.",tip:"Two forces in balance."}],
["E.5","Define",1,"Define a light year.","The distance light travels in a vacuum in one year (about 9.46 × 10¹⁵ m)|distance light travels|distance travelled by light|distance traveled by light|9.46 10 15",{model:"A light year is the distance light travels in a vacuum in one year, about 9.46 × 10¹⁵ m.",tip:"A distance, not a time."}],
["E.5","Outline",2,"Outline how a star's luminosity depends on its surface temperature and size.","Luminosity increases with the fourth power of surface temperature (L = σAT⁴)|t4|fourth power|hotter","And with surface area, i.e. a larger radius|surface area|radius|r2|bigger",{model:"L = σAT⁴: luminosity increases with the fourth power of surface temperature and with surface area.",tip:"Giants are luminous because they are big."}],
["E.5","Outline",2,"Outline what a white dwarf is.","The hot, dense core left when a low-mass star like the Sun dies|core|remnant|left over|low mass|sun",{model:"A white dwarf is the hot, dense core left by a low-mass star; no fusion occurs and it slowly cools, held up by electron degeneracy pressure.",tip:"About the size of the Earth."},"No fusion occurs; it slowly cools, supported by electron degeneracy pressure|no fusion|cools|electron degeneracy|degeneracy|earth sized"],
]);
